/* ================= parent app (phone) ================= */
const bandFor = age => age < 5 ? 'Seedling' : age < 8 ? 'Sprout' : age < 11 ? 'Explorer' : age < 14 ? 'Voyager' : 'Trailblazer';
const TABS = [['P08', 'home', 'Home'], ['P09', 'chart', 'Progress'], ['P10', 'plus', 'Create'], ['P16', 'wish', 'Rewards'], ['P18', 'gear', 'Settings']];
const TABOF = { P08: 'P08', P09: 'P09', P10: 'P10', P11: 'P10', P12: 'P10', P13: 'P10', P14: 'P10', P15: 'P10', P17: 'P10', P22: 'P10', P23: 'P10', P16: 'P16', P18: 'P18', P19: 'P18', P20: 'P18', P21: 'P18', P24: 'P18', P25: 'P18', P26: 'P18', P28: 'P18', P29: 'P18', P30: 'P18' };
const jp = o => o ? ` data-p='${esc(JSON.stringify(o))}'` : '';
function phone(title, body, o = {}) {
  const tab = TABOF[U.screen];
  if (D('parent') !== 'phone') {
    const nav = o.tabs === false || !tab ? '' : `<nav class="pw-side" aria-label="Main"><div class="brand">${buddySVG('zip', { size: 30, still: true })}${D('parent') === 'web' ? 'Trailbuddies' : ''}</div>${TABS.map(([to, ic, n]) => `<button type="button" data-to="${to}" ${tab === to ? 'aria-current="page"' : ''}>${I(ic)}${n}</button>`).join('')}${D('parent') === 'web' ? `<span style="flex:1"></span><div class="card" style="padding:10px;gap:2px"><b style="font-size:14px">${esc(S.family.parent)}</b><span class="mut">${esc(S.plan)}</span></div>` : ''}</nav>`;
    return `<div class="a ph pw${nav ? '' : ' solo'}">${nav}<div class="pw-main"><div class="pw-head">${o.back ? `<button type="button" class="back" data-to="${o.back}"${jp(o.bp)} aria-label="Back">${I('back')}</button>` : ''}<div style="flex:1;min-width:0"><h2>${esc(title)}</h2>${o.sub ? `<div class="mut">${o.sub}</div>` : ''}</div>${o.right || ''}</div>
      <div class="pw-body"><div class="pw-col"${o.wide ? ' style="max-width:1000px"' : ''}>${body}</div></div>${o.foot ? `<div class="pw-foot"><div class="pw-col">${o.foot}</div></div>` : ''}</div></div>`;
  }
  return `<div class="a ph"><div class="phd">${o.back ? `<button type="button" class="back" data-to="${o.back}"${jp(o.bp)} aria-label="Back">${I('back')}</button>` : ''}<div style="flex:1;min-width:0"><h2>${esc(title)}</h2>${o.sub ? `<div class="mut">${o.sub}</div>` : ''}</div>${o.right || ''}</div>
    <div class="pbd">${body}</div>${o.foot ? `<div class="pft">${o.foot}</div>` : ''}
    ${o.tabs === false || !tab ? '' : `<nav class="tabs">${TABS.map(([to, ic, n]) => `<button type="button" class="tab" data-to="${to}" ${tab === to ? 'aria-current="page"' : ''}>${I(ic)}${n}</button>`).join('')}</nav>`}</div>`;
}
const tgl = (on, act, k, label) => `<button type="button" class="tgl" role="switch" aria-checked="${!!on}" aria-label="${esc(label || k)}" data-act="${act}" data-k="${k}"></button>`;
const kids = () => S.learners;
const pk = () => learner(U.f.pk) || S.learners[0];
const kidChips = (act = 'pk', list = kids()) => `<div class="chips">${list.map(l => `<button type="button" class="chip" aria-pressed="${pk().id === l.id}" data-act="${act}" data-id="${l.id}">${esc(l.name)}</button>`).join('')}</div>`;
ACT.pk = (el, d) => { U.f.pk = d.id; render(); };
const field = (lab, inner) => `<div class="field"><label class="lbl">${lab}</label>${inner}</div>`;
const inp = (k, ph = '', extra = '') => `<input class="inp" data-f="${k}" value="${esc(U.f[k] ?? '')}" placeholder="${esc(ph)}" ${extra}>`;
function audit(what) { S.audit.unshift({ t: 'Today ' + new Date().toTimeString().slice(0, 5), who: S.family.parent, what }); }

/* ---------- onboarding ---------- */
R.P01 = { app: 'parent', note: 'Families start here without a school. Teachers have their own sign-up. Nothing about a child is collected before a grown-up has given consent.',
  render() { const big = D('parent') !== 'phone'; return `<div class="a ph" style="background:var(--leaf-deep);color:#fff;padding:${big ? '60px 40px' : '70px 26px 40px'};align-items:center;justify-content:center"><div class="welcome-in" style="${big ? '' : 'flex:1;justify-content:space-between;max-width:none'}">
    <div style="display:flex;flex-direction:column;gap:14px"><span style="font:800 13px var(--body);letter-spacing:.14em;color:var(--sun)">TRAILBUDDIES</span><h1 style="font-size:40px;color:#fff">Learning trails, with a buddy by their side.</h1><p style="margin:0;opacity:.9;font-size:16px">For children from 3, and anyone who wants to keep learning. No ads, no chat with strangers.</p></div>
    <div style="display:flex;justify-content:center;gap:0;margin:0 -10px">${['zip', 'tumi', 'juma', 'kiki'].map(b => buddySVG(b, { size: big ? 110 : 92 })).join('')}</div>
    <div style="display:flex;flex-direction:column;gap:10px"><button type="button" class="btn sun wide" data-act="obStart">Get started</button><button type="button" class="btn ghost wide" data-to="P08" style="background:transparent;color:#fff;border-color:#fff">I already have an account</button><button type="button" class="sim" data-to="T00" style="color:#d6eadb;border-color:#d6eadb">I’m a teacher → teacher sign-up</button></div></div></div>`; } };
ACT.obStart = () => { U.f.ob = { kids: [], email: 'grace@example.com' }; U.f.em = 'grace@example.com'; go('P02'); };
R.P02 = { app: 'parent', note: 'Email with a magic link, or Google / Apple. No password to forget. The country sets the privacy rules that apply (Kenya Data Protection Act, GDPR, COPPA).',
  render() { return phone('Create your account', `
    <div class="stepdots"><i class="on"></i><i></i><i></i><i></i><i></i></div>
    ${field('Your name', inp('nm', 'Grace'))}${field('Email', inp('em', 'you@example.com', 'type="email"'))}
    ${field('Country', `<select class="inp" data-f="ctry">${['Kenya', 'Uganda', 'Tanzania', 'United Kingdom', 'United States', 'Other'].map(c => `<option ${(U.f.ctry || 'Kenya') === c ? 'selected' : ''}>${c}</option>`).join('')}</select>`)}
    <button type="button" class="btn wide" data-act="signUp">Email me a sign-in link</button>
    <div style="text-align:center" class="mut">or</div><button type="button" class="btn ghost wide" data-act="signUp" data-sso="1">Continue with Google</button><button type="button" class="btn ghost wide" data-act="signUp" data-sso="1">Continue with Apple</button>
    <span class="mut">By continuing you agree to the Terms and Privacy Policy. We never sell data or show ads.</span>`, { back: 'P01', tabs: false }); } };
ACT.signUp = (el, d) => { const em = (U.f.em || '').trim(); if (!d.sso && !/^\S+@\S+\.\S+$/.test(em)) return toast('Enter a valid email address.'); if (U.f.nm) S.family.parent = U.f.nm; S.family.email = em || S.family.email; S.family.country = U.f.ctry || 'Kenya'; save(); go(d.sso ? 'P03' : 'P07'); };
R.P07 = { app: 'parent', note: p => p.expired ? 'Links expire after 15 minutes. A fresh one is one tap away; the email address is kept.' : 'The link opens the app on this phone. If it’s opened on another device, that device signs in instead.',
  render(p) { return phone(p.expired ? 'That link has expired' : 'Check your email', `
    <div style="height:150px;border-radius:22px;background:${p.expired ? 'var(--warn-soft)' : 'var(--sky-soft)'};display:grid;place-items:center;font-size:72px">${p.expired ? '⏳' : '✉️'}</div>
    ${p.expired ? `<p style="margin:0">Sign-in links work for 15 minutes. We can send a new one to <b>${esc(S.family.email)}</b>.</p><button type="button" class="btn wide" data-act="resend">Send a new link</button>` : `<p style="margin:0">We sent a sign-in link to <b>${esc(S.family.email)}</b>. Open it on this device.</p><button type="button" class="sim" data-to="P03">Simulate: tap the link in the email</button><button type="button" class="sim" data-to="P07" data-p='{"expired":1}'>Simulate: link has expired</button><button type="button" class="btn ghost wide" data-to="P02">Use a different email</button>`}`, { back: 'P02', tabs: false }); } };
ACT.resend = () => { go('P07'); toast('New link sent. It works for 15 minutes.'); };
R.P03 = { app: 'parent', note: 'Verifiable parental consent before any child profile exists. Each permission is plain-language and separate; optional ones start off.',
  render() { const c = U.f.cons || (U.f.cons = { core: false, voice: false, photos: false, research: false }); return phone('Before we start', `
    <div class="stepdots"><i class="on"></i><i class="on"></i><i></i><i></i><i></i></div>
    <p style="margin:0">You’re the parent or guardian, so you decide what Trailbuddies may do. You can change this any time in Settings.</p>
    <div class="list">${[['core', 'Save my child’s progress (needed)', 'Stars, lessons and badges, so they can carry on.'], ['voice', 'Record voices for lessons', 'Your voice on cards you make. Stays in your family.'], ['photos', 'Use photos I upload', 'Scanned for safety. Faces are never shared outside your family.'], ['research', 'Help improve lessons (anonymous)', 'Which questions are hard, never who answered.']].map(([k, t, d]) => `<div class="ln" style="align-items:flex-start"><span><b>${t}</b><br><span class="mut">${d}</span></span>${tgl(c[k], 'cons', k, t)}</div>`).join('')}</div>
    <div class="card" style="flex-direction:row;gap:10px;align-items:center">${I('shield')}<span class="mut">To confirm you’re an adult we send a one-time code to your phone (or a KSh 0 card check).</span></div>`, { back: 'P02', tabs: false, foot: `<button type="button" class="btn wide" data-act="consentNext" ${c.core ? '' : 'disabled'}>I agree, continue</button>` }); } };
ACT.cons = (el, d) => { U.f.cons[d.k] = !U.f.cons[d.k]; render(); };
ACT.consentNext = () => { audit('Gave parental consent'); U.f.ob = U.f.ob || { kids: [] }; go('P04'); };
R.P04 = { app: 'parent', note: 'Add one or more learners: a first name (or nickname) and birth year. The band (Seedling, Sprout, Explorer, Voyager, Trailblazer) is worked out from age. Adults can learn too.',
  render() { const ob = U.f.ob || (U.f.ob = { kids: [] }); const age = 2026 - (+U.f.ky || 0);
    return phone('Who’s learning?', `
    <div class="stepdots"><i class="on"></i><i class="on"></i><i class="on"></i><i></i><i></i></div>
    ${ob.kids.map((k, i) => `<div class="card" style="flex-direction:row;align-items:center;gap:12px">${avatar(k, 44)}<span style="flex:1"><b>${esc(k.name)}</b><br><span class="mut">Age ${k.age} · ${k.band}</span></span><button type="button" class="back" data-act="obDel" data-i="${i}" aria-label="Remove">${I('x')}</button></div>`).join('')}
    <div class="card" style="gap:10px">${field('First name or nickname', inp('kn', 'e.g. Baraka'))}${field('Birth year', inp('ky', '2020', 'inputmode="numeric" data-live="1"'))}${U.f.ky && age >= 3 && age < 120 ? `<span class="pill ok" style="align-self:flex-start">Age ${age} · ${bandFor(age)}</span>` : U.f.ky && age < 3 ? '<span class="pill warn" style="align-self:flex-start">Trailbuddies is for ages 3 and up</span>' : ''}
      <button type="button" class="btn ghost" data-act="obAdd">${I('plus')} Add learner</button></div>
    <span class="mut">Only a first name and birth year. No surnames, schools or photos of the child are needed.</span>`, { back: 'P03', tabs: false, foot: `<button type="button" class="btn wide" data-to="P05" ${ob.kids.length ? '' : 'disabled'}>Continue</button>` }); } };
ACT.obAdd = () => { const n = (U.f.kn || '').trim(); const age = 2026 - (+U.f.ky || 0); if (!n) return toast('Add a name.'); if (!(age >= 3 && age < 120)) return toast('Enter a birth year for ages 3 and up.'); U.f.ob.kids.push({ name: n, age, year: +U.f.ky, band: bandFor(age), color: pick(['leaf', 'berry', 'sun', 'sky']), interests: [], start: 'begin' }); U.f.kn = ''; U.f.ky = ''; render(); };
ACT.obDel = (el, d) => { U.f.ob.kids.splice(+d.i, 1); render(); };
R.P05 = { app: 'parent', note: 'Interests decide which places glow first on the child’s map. "Show what you know" runs a 2-minute placement quiz so nobody is bored.',
  render() { const ob = U.f.ob; const i = U.f.obi || 0; const k = ob.kids[i];
    if (!k) return phone('Interests', '<span class="mut">Add a learner first.</span>', { back: 'P04', tabs: false });
    return phone(`What does ${k.name} love?`, `
    <div class="stepdots"><i class="on"></i><i class="on"></i><i class="on"></i><i class="on"></i><i></i></div>
    ${ob.kids.length > 1 ? `<div class="chips">${ob.kids.map((x, j) => `<button type="button" class="chip" aria-pressed="${i === j}" data-act="obi" data-i="${j}">${esc(x.name)}</button>`).join('')}</div>` : ''}
    <div class="chips">${[['animals', 'Animals'], ['numbers', 'Numbers'], ['language', 'Letters & words'], ['colours', 'Colours & art'], ['shapes', 'Shapes'], ['space', 'Space'], ['weather', 'Weather'], ['vehicles', 'Vehicles'], ['sports', 'Sports'], ['music', 'Music']].map(([v, n]) => `<button type="button" class="chip" aria-pressed="${k.interests.includes(v)}" data-act="obInt" data-v="${v}">${n}</button>`).join('')}</div>
    <b>Where should ${esc(k.name)} start?</b>
    <div class="list">${[['begin', 'From the beginning', 'Gentle first steps. Best for most children.'], ['place', 'Show what you know', 'A 2-minute quiz finds the right starting point.']].map(([v, t, d]) => `<button type="button" class="ln" data-act="obStartAt" data-v="${v}" style="width:100%;border-left:0;border-right:0;border-top:0;background:none;text-align:left;color:var(--ink)"><span><b>${t}</b><br><span class="mut">${d}</span></span><span class="pill ${k.start === v ? 'ok' : ''}">${k.start === v ? 'Chosen' : ''}</span></button>`).join('')}</div>`, { back: 'P04', tabs: false, foot: `<button type="button" class="btn wide" data-to="P06">Continue</button>` }); } };
ACT.obi = (el, d) => { U.f.obi = +d.i; render(); };
ACT.obInt = (el, d) => { const k = U.f.ob.kids[U.f.obi || 0]; const a = k.interests; a.includes(d.v) ? a.splice(a.indexOf(d.v), 1) : a.push(d.v); render(); };
ACT.obStartAt = (el, d) => { U.f.ob.kids[U.f.obi || 0].start = d.v; render(); };
R.P06 = { app: 'parent', note: 'Sensible defaults (20 minutes a day, a 2-lesson goal), then hand the device to the child. Their profile opens on the learner app.',
  render() { const ob = U.f.ob || { kids: [] }; return phone('Family settings', `
    <div class="stepdots"><i class="on"></i><i class="on"></i><i class="on"></i><i class="on"></i><i class="on"></i></div>
    <div class="list">
      <div class="ln"><span><b>Daily time limit</b><br><span class="mut">The lesson finishes, then a calm goodbye</span></span><span style="display:flex;align-items:center;gap:8px"><button type="button" class="back" data-act="lim" data-v="-5" aria-label="Less">−</button><b class="tnum">${S.settings.limit} min</b><button type="button" class="back" data-act="lim" data-v="5" aria-label="More">+</button></span></div>
      <div class="ln"><span><b>Daily goal</b></span><div class="seg" style="width:150px">${[1, 2, 3].map(n => `<button type="button" aria-pressed="${S.settings.goal === n}" data-act="setGoal" data-v="${n}">${n}</button>`).join('')}</div></div>
      <div class="ln"><span><b>Buddy talks out loud</b></span>${tgl(S.settings.voice, 'tset', 'voice')}</div>
      <div class="ln"><span><b>Calm mode</b><br><span class="mut">No confetti or fast movement</span></span>${tgl(S.settings.calm, 'tset', 'calm')}</div>
      <div class="ln"><span><b>Weekly email digest</b></span>${tgl(S.settings.digest, 'tset', 'digest')}</div></div>
    <div class="card" style="background:var(--sun-soft);border-color:var(--sun-deep)"><b>Ready to hand over</b><span>${ob.kids.length ? ob.kids.map(k => esc(k.name)).join(', ') + ' will choose a buddy first.' : 'Your learners will choose a buddy first.'} The grown-up zone stays behind a gate.</span></div>`, { back: 'P05', tabs: false, foot: `<button type="button" class="btn sun wide" data-act="handOver">Hand to my child</button><button type="button" class="btn ghost wide" data-act="obFinish">Go to my parent home</button>` }); } };
ACT.lim = (el, d) => { S.settings.limit = Math.max(5, Math.min(90, S.settings.limit + +d.v)); save(); render(); };
ACT.setGoal = (el, d) => { S.settings.goal = +d.v; save(); render(); };
ACT.tset = (el, d) => { S.settings[d.k] = !S.settings[d.k]; save(); render(); };
function obCommit() {
  const ob = U.f.ob; if (!ob || !ob.kids.length) return null; let first = null;
  ob.kids.forEach(k => { const id = k.name.toLowerCase().replace(/[^a-z]/g, '') + Math.floor(Math.random() * 90 + 10); if (!first) first = id; S.learners.push({ id, name: k.name, age: k.age, born: String(k.year), band: k.band, adult: k.age >= 18, color: k.color, buddy: null, outfit: {}, owned: [], room: {}, ownedRoom: [], stars: 0, treasures: 0, progress: {}, badges: [], mastery: {}, pictures: shuffle(Object.keys(PICS)).slice(0, 3), pw: false, lang: 'en', bilingual: false, today: 0, minutes: 0, week: [0, 0, 0, 0, 0, 0, 0], games: [], flags: {}, interests: k.interests, start: k.start, wishes: [] }); });
  audit('Added ' + ob.kids.map(k => k.name).join(', ')); U.f.ob = { kids: [] }; save(); return first;
}
ACT.handOver = () => { const id = obCommit(); if (id) S.active = id; save(); go('C01'); toast('Pick your new profile, then choose a buddy.'); };
ACT.obFinish = () => { obCommit(); go('P08'); };

/* ---------- home & progress ---------- */
const asked = () => S.wishes.filter(w => w.status === 'asked');
R.P08 = { app: 'parent', note: 'Today at a glance for every learner, plus anything waiting on a grown-up: wishes to approve, rewards to deliver. Everything here updates live from the learner app.',
  render() {
    const a = asked(); const td = S.toDeliver.filter(t => !t.done); const goal = S.settings.goal; const big = D('parent') !== 'phone';
    return phone(`Hello, ${S.family.parent}`, `
      ${a.length || td.length ? `<div class="card" style="background:var(--sun-soft);border-color:var(--sun-deep);gap:8px"><b>Waiting for you</b>${a.map(w => `<div class="row"><span>${esc(learner(w.learner).name)} asked for <b>${esc(w.title)}</b></span><button type="button" class="btn sm" data-to="P16">Review</button></div>`).join('')}${td.map(t => `<div class="row"><span>Deliver <b>${esc(t.real)}</b> to ${esc(learner(t.learner).name)}</span><button type="button" class="btn sm ghost" data-to="P16">Open</button></div>`).join('')}</div>` : ''}
      <div class="${big ? 'dash three' : ''}" style="${big ? '' : 'display:contents'}">${kids().map(l => `<button type="button" class="card" data-act="openKid" data-id="${l.id}" style="text-align:left;gap:10px;color:var(--ink)"><span class="row" style="justify-content:flex-start;gap:12px">${avatar(l, 46)}<span style="flex:1"><b style="font-size:17px">${esc(l.name)}</b><br><span class="mut">${l.adult ? 'Adult learner' : 'Age ' + l.age} · ${l.band}</span></span>${l.buddy ? buddySVG(l.buddy, { size: 46, outfit: l.outfit, still: true }) : '<span class="pill sun">New</span>'}</span>
        <span class="row"><span class="mut">Today: ${l.today} of ${goal} lessons · ${l.minutes} min</span><span style="display:flex;gap:10px;font-weight:800"><span style="display:flex;align-items:center;gap:3px">${STAR(true, 18)}${l.stars}</span><span style="display:flex;align-items:center;gap:3px">${GEM(18)}${l.treasures}</span></span></span><div class="bar"><i style="width:${Math.min(100, l.today / goal * 100)}%"></i></div></button>`).join('')}</div>
      <div style="display:grid;grid-template-columns:${big ? 'repeat(4,minmax(0,1fr))' : '1fr 1fr'};gap:10px">${[['P10', 'book', 'Make a lesson'], ['P14', 'badge', 'Make a badge'], ['P16', 'wish', 'Wishes & awards'], ['P04', 'plus', 'Add a learner']].map(([to, ic, n]) => `<button type="button" class="card" data-act="${to === 'P04' ? 'addMore' : 'go'}" data-to="${to}" style="align-items:flex-start;color:var(--ink)">${I(ic)}<b>${n}</b></button>`).join('')}</div>
      <div class="card"><b>This week</b><span class="mut">${S.learners.reduce((n, l) => n + l.week.reduce((a, b) => a + b, 0), 0)} minutes of learning across the family. Weekly digest ${S.settings.digest ? 'arrives Sunday evening' : 'is off'}.</span></div>
      <button type="button" class="sim" data-to="C01">Switch to the learner app</button>`, { wide: true, right: `<button type="button" class="back" data-to="P30" aria-label="Help">${I('help')}</button>`, sub: S.plan === 'Free' ? 'Free plan' : esc(S.plan) });
  } };
ACT.openKid = (el, d) => { U.f.pk = d.id; go('P09'); };
ACT.addMore = () => { U.f.ob = { kids: [] }; go('P04'); };
R.P09 = { app: 'parent', note: 'Progress in plain words: what they did, what they’re good at, what’s tricky (with a tip to help at home). Never ranked against other children.',
  render() {
    const l = pk(); const days = ['M', 'T', 'W', 'T', 'F', 'S', 'S']; const mx = Math.max(30, ...l.week);
    const weak = Object.entries(l.mastery).filter(([k, v]) => v[1] / v[0] < .7).map(([k]) => { let f = null; SUBJECTS.forEach(s => s.units.forEach(u => u.items.forEach(it => { if (it.id === k) f = it; }))); return f; }).filter(Boolean);
    const big = D('parent') !== 'phone';
    return phone('Progress', `${kidChips()}<div class="${big ? 'dash' : ''}" style="${big ? '' : 'display:contents'}">
      <div class="card"><div class="row"><b>Minutes this week</b><span class="mut tnum">${l.week.reduce((a, b) => a + b, 0)} min</span></div><div class="bars">${l.week.map((m, i) => `<div><i class="${i === 6 ? 'today' : ''}" style="height:${m / mx * 90}%"></i>${days[i]}</div>`).join('')}</div></div>
      <div class="card" style="gap:10px"><b>Subjects</b>${SUBJECTS.map(s => { const tot = s.units.length * 4; const done = s.units.reduce((n, u) => n + lessonIds(u).filter(k => l.progress[k]).length + (l.progress[u.id + '-T'] ? 1 : 0), 0); return `<div><div class="row"><span>${esc(s.name)}</span><span class="mut tnum">${done} / ${tot}</span></div><div class="bar"><i style="width:${done / tot * 100}%"></i></div></div>`; }).join('')}</div>
      <div class="card"><b>Tricky right now</b>${weak.length ? weak.map(it => `<div class="row" style="justify-content:flex-start;gap:10px"><span class="pic" style="width:40px;height:40px;font-size:22px">${art(it, 24)}</span><span style="flex:1"><b>${esc(it.label)}</b><br><span class="mut">Coming back in review. Tip: spot one together today.</span></span></div>`).join('') : '<span class="mut">Nothing tricky. Lovely!</span>'}</div>
      <div class="card"><div class="row"><b>Badges</b><span class="mut">${l.badges.length} earned</span></div><div style="display:flex;gap:6px;flex-wrap:wrap">${l.badges.map(id => allBadges().find(b => b.id === id)).filter(Boolean).map(b => `<span title="${esc(b.name)}">${badgeArt(b, 52)}</span>`).join('') || '<span class="mut">None yet</span>'}</div><button type="button" class="btn sm ghost" data-to="P16" data-p='{"tab":"award"}'>Award a badge</button></div></div>
      <button type="button" class="sim" data-act="playAs" data-id="${l.id}">Open the learner app as ${esc(l.name)}</button>`, { wide: true });
  } };
ACT.playAs = (el, d) => { S.active = d.id; save(); const l = L(); go(l.adult ? 'A01' : l.buddy ? 'C04' : 'C03'); };

/* ---------- lesson builder ---------- */
const EMOJI = ['\u{1F415}', '\u{1F408}', '\u{1F404}', '\u{1F414}', '\u{1F41F}', '\u{1F98B}', '\u{1F333}', '\u{1F33B}', '\u{1F34E}', '\u{1F34C}', '\u{1F697}', '\u{1F6B2}', '\u{1F3E0}', '\u{26BD}', '\u{1F9F8}', '\u{1F45F}'];
function draft() { return U.f.draft || (U.f.draft = { id: uid('c'), title: '', cards: [], template: 'learn', assigned: [], fresh: true }); }
R.P10 = { app: 'parent', note: 'Make a lesson from your own photos, words and voice: your pets, your home, this week’s spelling. Your lessons are listed below; tap one to edit.',
  render() { const d = draft(); const mine = S.customLessons.filter(c => !c.draft);
    return phone('Lesson Builder', `
      ${field('Lesson name', inp('dtitle', 'e.g. Our Pets', `data-live="1"`).replace(`value="${esc(U.f.dtitle ?? '')}"`, `value="${esc(U.f.dtitle ?? d.title)}"`))}
      <div class="row"><b>Cards (${d.cards.length})</b><span class="mut">3 to 12 cards</span></div>
      ${d.cards.map((c, i) => `<div class="card" style="flex-direction:row;align-items:center;gap:12px"><span class="pic">${c.img ? `<img src="${c.img}" alt="">` : c.e}</span><span style="flex:1;min-width:0"><b>${esc(c.label)}</b><br><span class="mut">${c.rec ? 'Your voice' : 'Device voice'}${c.tag ? ' · ' + esc(c.tag) : ''}</span></span><button type="button" class="back" data-act="delCard" data-i="${i}" aria-label="Remove card">${I('x')}</button></div>`).join('')}
      <button type="button" class="btn ghost" data-act="newCard">${I('plus')} Add a card</button>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><button type="button" class="card" data-to="P22" style="color:var(--ink)">${I('sparkle')}<b>Remix a built-in unit</b></button><button type="button" class="card" data-to="P23" style="color:var(--ink)">${I('share')}<b>Import by code</b></button><button type="button" class="card" data-to="P13" style="color:var(--ink)">${I('trail')}<b>Make a trail</b></button><button type="button" class="card" data-to="P14" style="color:var(--ink)">${I('badge')}<b>Badge Studio</b></button></div>
      ${mine.length ? `<b>My lessons</b><div class="list">${mine.map(c => `<button type="button" class="ln" data-act="editLesson" data-id="${c.id}" style="width:100%;border-left:0;border-right:0;border-top:0;background:none;color:var(--ink);text-align:left"><span><b>${esc(c.title)}</b><br><span class="mut">${c.cards.length} cards · for ${c.assigned.map(id => (learner(id) || { name: id }).name).join(', ') || 'nobody yet'}</span></span>${I('back', 'ico')}</button>`).join('')}</div>` : ''}`,
      { foot: `<button type="button" class="btn wide" data-act="toTemplate" ${d.cards.length >= 3 ? '' : 'disabled'}>Next: choose a game</button>${d.cards.length < 3 ? `<span class="mut" style="text-align:center">Add ${3 - d.cards.length} more card${3 - d.cards.length > 1 ? 's' : ''}</span>` : ''}` }); } };
ACT.newCard = () => { draft().title = U.f.dtitle ?? draft().title; U.f.card = { e: EMOJI[0], label: '', fact: '', tag: '', rec: false, img: null }; go('P11'); };
ACT.delCard = (el, d) => { draft().cards.splice(+d.i, 1); render(); };
ACT.editLesson = (el, d) => { const c = S.customLessons.find(x => x.id === d.id); U.f.draft = JSON.parse(JSON.stringify(c)); U.f.dtitle = c.title; render(); toast('Editing “' + c.title + '”.'); };
ACT.toTemplate = () => { const d = draft(); d.title = (U.f.dtitle ?? d.title).trim() || 'My lesson'; go('P12'); };
R.P11 = { app: 'parent', note: 'Take or choose a photo (resized on the phone before upload and scanned for safety), or use a picture. Record your own voice saying the name; otherwise the buddy says it.',
  render() { const c = U.f.card || (U.f.card = { e: EMOJI[0], label: '', rec: false });
    return phone('Add a card', `
      <div style="height:200px;border-radius:22px;background:var(--sand);display:grid;place-items:center;font-size:110px;overflow:hidden;position:relative">${c.img ? `<img src="${c.img}" alt="" style="width:100%;height:100%;object-fit:cover">` : c.e}${c.scan ? `<span class="pill ${c.scan === 'ok' ? 'ok' : 'sun'}" style="position:absolute;left:10px;top:10px">${c.scan === 'ok' ? 'Safety check passed' : 'Checking…'}</span>` : ''}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="btn ghost" style="cursor:pointer">${I('camera')} Photo<input type="file" accept="image/*" data-file="cardPhoto" style="display:none"></label><button type="button" class="btn ghost" data-act="toggleEmoji">${I('image')} Picture</button></div>
      ${U.f.emo ? `<div style="display:grid;grid-template-columns:repeat(8,1fr);gap:6px">${EMOJI.map(e => `<button type="button" data-act="pickEmoji" data-e="${e}" style="font-size:26px;border:2px solid ${c.e === e && !c.img ? 'var(--leaf)' : 'var(--aline)'};border-radius:10px;background:var(--card);padding:4px">${e}</button>`).join('')}</div>` : ''}
      ${field('Name on the card', `<input class="inp" data-f="clabel" value="${esc(U.f.clabel ?? c.label)}" placeholder="e.g. Simba the dog">`)}
      ${field('A fun fact (optional)', `<input class="inp" data-f="cfact" value="${esc(U.f.cfact ?? c.fact ?? '')}" placeholder="Simba loves chasing balls.">`)}
      ${field('Group, for sorting games (optional)', `<div class="chips">${['land', 'water', 'air', 'home', 'outside'].map(t => `<button type="button" class="chip" aria-pressed="${c.tag === t}" data-act="cTag" data-t="${t}">${t}</button>`).join('')}</div>`)}
      <div class="card" style="flex-direction:row;align-items:center;gap:12px"><button type="button" class="speak" data-act="recCard" aria-label="Record your voice">${I('mic')}</button><span style="flex:1"><b>${U.f.recing ? 'Recording…' : c.rec ? 'Your voice is saved' : 'Record the name'}</b><br><span class="mut">${c.rec ? 'Tap the mic to re-record' : 'Hold the phone close and say it clearly'}</span></span>${c.rec ? `<button type="button" class="btn sm ghost" data-act="say" data-text="${esc(U.f.clabel ?? c.label)}">Play</button>` : ''}</div>`,
      { back: 'P10', foot: `<button type="button" class="btn wide" data-act="saveCard">Save card</button>` }); } };
ACT.toggleEmoji = () => { U.f.emo = !U.f.emo; render(); };
ACT.pickEmoji = (el, d) => { U.f.card.e = d.e; U.f.card.img = null; U.f.card.scan = null; render(); };
ACT.cTag = (el, d) => { U.f.card.tag = U.f.card.tag === d.t ? '' : d.t; render(); };
ACT.recCard = () => { U.f.recing = true; render(); setTimeout(() => { U.f.recing = false; U.f.card.rec = true; if (R[U.screen] && U.screen === 'P11') render(); }, 1400); };
ACT.cardPhoto = el => {
  const f = el.files && el.files[0]; if (!f) return; const rd = new FileReader();
  rd.onload = () => { const im = new Image(); im.onload = () => { const s = 360, c = document.createElement('canvas'); c.width = c.height = s; const g = c.getContext('2d'); const m = Math.min(im.width, im.height); g.drawImage(im, (im.width - m) / 2, (im.height - m) / 2, m, m, 0, 0, s, s); U.f.card.img = c.toDataURL('image/jpeg', .78); U.f.card.scan = 'wait'; render(); setTimeout(() => { if (U.f.card) { U.f.card.scan = 'ok'; if (U.screen === 'P11') render(); } }, 1200); }; im.src = rd.result; };
  rd.readAsDataURL(f);
};
ACT.saveCard = () => { const c = U.f.card; const label = (U.f.clabel ?? c.label).trim(); if (!label) return toast('Give the card a name.'); draft().cards.push({ id: uid('k'), label, e: c.e, img: c.img, fact: (U.f.cfact || '').trim(), tag: c.tag, rec: c.rec }); U.f.card = null; U.f.clabel = undefined; U.f.cfact = undefined; U.f.emo = false; go('P10'); };
R.P12 = { app: 'parent', note: 'Pick how the cards are played, choose who gets it, preview it exactly as a child sees it, then publish. It appears on Family & Class Island straight away.',
  render() { const d = draft(); const tags = new Set(d.cards.map(c => c.tag).filter(Boolean));
    return phone(d.title || 'My lesson', `
      <b>How should it be played?</b>
      <div class="list">${[['learn', 'Learn the names', 'Meet each card, then tap and match'], ['sort', 'Sort into groups', tags.size >= 2 ? 'Uses the groups you set' : 'Needs at least 2 groups on the cards'], ['puzzle', 'Picture puzzle', 'A jigsaw of the first card, then name it']].map(([v, t, s]) => `<button type="button" class="ln" data-act="tpl" data-v="${v}" style="width:100%;border-left:0;border-right:0;border-top:0;background:none;color:var(--ink);text-align:left" ${v === 'sort' && tags.size < 2 ? 'disabled' : ''}><span><b>${t}</b><br><span class="mut">${s}</span></span><span class="pill ${d.template === v ? 'ok' : ''}">${d.template === v ? 'Chosen' : ''}</span></button>`).join('')}</div>
      <b>Who is it for?</b><div class="chips">${kids().map(l => `<button type="button" class="chip" aria-pressed="${d.assigned.includes(l.id)}" data-act="asg" data-id="${l.id}">${esc(l.name)}</button>`).join('')}</div>
      <div class="card" style="flex-direction:row;gap:10px;align-items:center">${I('share')}<span class="mut" style="flex:1">After publishing you can get a share code for other families or a teacher.</span></div>
      <button type="button" class="btn ghost" data-act="previewLesson">${I('play')} Preview as a child</button>`,
      { back: 'P10', foot: `<button type="button" class="btn sun wide" data-act="publish" ${d.assigned.length ? '' : 'disabled'}>Publish to ${d.assigned.length ? d.assigned.map(id => learner(id).name).join(' & ') : '…'}</button>` }); } };
ACT.tpl = (el, d) => { draft().template = d.v; render(); };
ACT.asg = (el, d) => { const a = draft().assigned; a.includes(d.id) ? a.splice(a.indexOf(d.id), 1) : a.push(d.id); render(); };
function upsertDraft(pub) { const d = draft(); const i = S.customLessons.findIndex(c => c.id === d.id); const rec = { id: d.id, title: d.title, by: d.by || 'Mum', template: d.template, cards: d.cards, assigned: pub ? d.assigned.slice() : (i >= 0 ? S.customLessons[i].assigned : []), draft: pub ? false : (i >= 0 ? S.customLessons[i].draft : true) }; if (i >= 0) S.customLessons[i] = rec; else S.customLessons.push(rec); save(); return rec; }
ACT.previewLesson = () => { const rec = upsertDraft(false); startLesson({ kind: 'custom', id: rec.id, preview: true }); };
ACT.publish = () => { const rec = upsertDraft(true); audit('Published lesson “' + rec.title + '”'); const who = rec.assigned[0]; U.f.draft = null; U.f.dtitle = undefined;
  overlay(`<div class="dialog" style="align-items:center;text-align:center">${buddySVG('zip', { size: 90, mood: 'cheer' })}<h2 style="font-size:24px">“${esc(rec.title)}” is live</h2><p class="mut" style="margin:0">It’s waiting on Family & Class Island for ${rec.assigned.map(id => esc(learner(id).name)).join(' and ')}.</p><button type="button" class="btn wide" data-act="seeIsland" data-id="${who}">See it on the tablet</button><button type="button" class="btn ghost wide" data-act="shareLesson" data-id="${rec.id}">Get a share code</button><button type="button" class="btn ghost wide" data-act="closeGo" data-to2="P08">Done</button></div>`); };
