R.P24 = { app: 'parent', note: 'Checkout with M-Pesa or card. Nothing is charged during the 14-day trial; a reminder comes 2 days before it ends.',
  render() { const per = U.f.per || 'year'; const pay = U.f.pay || 'mpesa';
    return phone('Checkout', `<div class="card"><div class="row"><b>Family Plus, ${per === 'year' ? 'yearly' : 'monthly'}</b><b>${per === 'year' ? 'KSh 4,900' : 'KSh 590'}</b></div><span class="mut">Free for 14 days, then billed. Cancel any time.</span></div>
      <div class="seg"><button type="button" aria-pressed="${pay === 'mpesa'}" data-act="pay" data-v="mpesa">M-Pesa</button><button type="button" aria-pressed="${pay === 'card'}" data-act="pay" data-v="card">Card</button></div>
      ${pay === 'mpesa' ? field('M-Pesa phone number', inp('mp', '07xx xxx xxx', 'inputmode="tel"')) : `${field('Card number', inp('cn', '4242 4242 4242 4242'))}<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${inp('ce', 'MM/YY')}${inp('cc', 'CVC')}</div>`}
      <span class="mut">${pay === 'mpesa' ? 'You’ll get a prompt on your phone to approve with your PIN.' : 'Prototype only. No real payment is taken.'}</span>`, { back: 'P21', foot: `<button type="button" class="btn sun wide" data-act="checkout">Start free trial</button>` }); } };
ACT.pay = (el, d) => { U.f.pay = d.v; render(); };
ACT.checkout = () => { if ((U.f.pay || 'mpesa') === 'mpesa' && !(U.f.mp || '').replace(/\D/g, '').match(/^0?7\d{8}$|^2547\d{8}$/)) return toast('Enter an M-Pesa number like 0712 345 678.'); overlay(`<div class="dialog" style="align-items:center;text-align:center"><div style="font-size:54px">\u{1F4F1}</div><h2 style="font-size:22px">Approve on your phone</h2><p class="mut" style="margin:0">Enter your M-Pesa PIN in the prompt. (KSh 0 today.)</p><button type="button" class="sim" data-act="payOk">Simulate: PIN entered</button></div>`); };
ACT.payOk = () => { S.plan = 'Family Plus (trial)'; audit('Started Family Plus trial'); save(); U.overlay = null; go('P21'); toast('Family Plus trial started. Receipt sent to ' + S.family.email + '.'); };
R.P25 = { app: 'parent', note: 'Cancelling is as easy as subscribing. Plus features stay until the end of the paid period; nothing a child earned is taken away.',
  render() { return phone('Cancel Family Plus', `<p style="margin:0">Your plan stays active until <b>5 Nov</b>. After that you move to Free. Stars, badges and progress are kept; extra custom lessons become read-only.</p>
      <b>Can we ask why? (optional)</b><div class="chips">${['Too expensive', 'Not using it', 'Missing a feature', 'Child lost interest', 'Other'].map(r => `<button type="button" class="chip" aria-pressed="${U.f.why === r}" data-act="why" data-v="${r}">${r}</button>`).join('')}</div>`, { back: 'P21', foot: `<button type="button" class="btn bad wide" data-act="cancelPlan">Cancel subscription</button><button type="button" class="btn ghost wide" data-to="P21">Keep Family Plus</button>` }); } };
ACT.why = (el, d) => { U.f.why = d.v; render(); };
ACT.cancelPlan = () => { S.plan = 'Free'; audit('Cancelled Family Plus'); save(); go('P21'); toast('Cancelled. Plus stays until 5 Nov.'); };
R.P26 = { app: 'parent', note: 'Reference board of parent-facing states: offline, storage full, upload failed, and a server error with a retry that keeps the user’s work.',
  render() { const box = (t, d, b, tone) => `<div class="card" style="gap:6px;border-color:var(--${tone});background:var(--${tone}-soft)"><b>${t}</b><span class="mut">${d}</span>${b ? `<button type="button" class="btn sm ghost" data-act="toast" data-msg="${esc(b[1])}" style="align-self:flex-start">${b[0]}</button>` : ''}</div>`;
    return phone('States', `${box('You’re offline', 'Changes are saved on this phone and sync when you’re back online.', null, 'sky')}${box('Phone storage is nearly full', 'Downloads for offline play are paused. Remove a downloaded subject to free 120 MB.', ['Manage downloads', 'Downloads: Numbers 80 MB, Animals 120 MB.'], 'warn')}${box('Photo didn’t upload', 'The card is saved without it. Try again on Wi-Fi.', ['Try again', 'Uploaded.'], 'warn')}${box('Something went wrong', 'Your lesson draft is safe. We’ve been told about the problem.', ['Retry', 'Done. Draft saved.'], 'bad')}${box('Empty: no lessons yet', 'Make your first lesson from your own photos in about 3 minutes.', ['Make a lesson', 'Opens the Lesson Builder.'], 'sun')}`, { back: 'P18' }); } };
R.P28 = { app: 'parent', note: 'Record how your family says each letter sound, so phonics matches home. Recordings replace the buddy’s voice for that letter.',
  render() { const ls = S.letterSounds; const all = 'satpinmdgockeurhbflj'.split(''); const n = all.filter(c => ls[c]).length;
    return phone('Letter sounds', `<div class="row"><span class="mut">${n} of ${all.length} recorded</span><div class="bar" style="width:140px"><i style="width:${n / all.length * 100}%"></i></div></div>
      <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:8px">${all.map(c => `<button type="button" data-act="recLetter" data-c="${c}" style="height:62px;border-radius:14px;border:2px solid ${U.f.recL === c ? 'var(--coral)' : ls[c] ? 'var(--leaf)' : 'var(--aline)'};background:${ls[c] ? 'var(--leaf-soft)' : 'var(--card)'};font:800 26px var(--display);color:var(--ink)">${c}</button>`).join('')}</div>
      <div class="card" style="flex-direction:row;align-items:center;gap:12px"><span class="speak">${I('mic')}</span><span>${U.f.recL ? `Recording “${U.f.recL}”…` : 'Tap a letter to record its sound. Green letters are done; tap again to re-record.'}</span></div>`, { back: 'P18' }); } };
ACT.recLetter = (el, d) => { U.f.recL = d.c; render(); setTimeout(() => { S.letterSounds[d.c] = true; U.f.recL = null; save(); if (U.screen === 'P28') render(); }, 1100); };
R.P29 = { app: 'parent', note: 'The parent app and each learner can use different languages. Bilingual mode shows English and Kiswahili side by side in lessons.',
  render() { const l = pk(); return phone('Languages', `<b>Parent app language</b><div class="seg">${['English', 'Kiswahili', 'Français'].map(x => `<button type="button" aria-pressed="${(S.family.ui || 'English') === x}" data-act="uiLang" data-v="${x}">${x}</button>`).join('')}</div>
      <b>Learning language</b>${kidChips()}<div class="list">${[['en', 'English'], ['sw', 'Kiswahili'], ['bi', 'Bilingual: English + Kiswahili']].map(([v, n]) => { const cur = v === 'bi' ? l.bilingual : !l.bilingual && l.lang === v; return `<button type="button" class="ln" data-act="kidLang" data-v="${v}" style="width:100%;border-left:0;border-right:0;border-top:0;background:none;color:var(--ink);text-align:left"><b>${n}</b><span class="pill ${cur ? 'ok' : ''}">${cur ? 'On' : ''}</span></button>`; }).join('')}</div>
      <span class="mut">Kiswahili covers Numbers and Animals in the MVP; more subjects follow.</span>`, { back: 'P18' }); } };
ACT.uiLang = (el, d) => { S.family.ui = d.v; save(); render(); if (d.v !== 'English') toast('Translations are in progress. The prototype stays in English.'); };
ACT.kidLang = (el, d) => { const l = pk(); if (d.v === 'bi') { l.bilingual = true; l.lang = 'en'; } else { l.bilingual = false; l.lang = d.v; } save(); render(); toast(`${l.name}’s lessons now use ${d.v === 'bi' ? 'English and Kiswahili' : d.v === 'sw' ? 'Kiswahili' : 'English'}.`); };
R.P30 = { app: 'parent', note: 'Short answers to common questions, a contact form that replies within a working day, and a direct way to report a safety concern.',
  render() { const faq = [['How do I stop my child leaving the app?', 'Use Guided Access (iPhone) or Screen Pinning (Android). Trailbuddies never shows links out.'], ['Do stars ever go down?', 'Never. Treasures are spent in the shop, but stars and badges are kept forever.'], ['Can two children share a tablet?', 'Yes. Each picks their own profile; add picture passwords if they peek.'], ['Is my child’s data shared?', 'No ads, no selling data. Teachers see only what you allow.']];
    return phone('Help & support', `<div class="list">${faq.map(([q, a], i) => `<button type="button" class="ln" data-act="faq" data-i="${i}" style="width:100%;border-left:0;border-right:0;border-top:0;background:none;color:var(--ink);text-align:left;flex-direction:column;align-items:flex-start"><b>${q}</b>${U.f.faq === i ? `<span class="mut">${a}</span>` : ''}</button>`).join('')}</div>
      <div class="card" style="gap:10px"><b>Contact us</b><textarea class="inp" data-f="msg" placeholder="How can we help?">${esc(U.f.msg || '')}</textarea><button type="button" class="btn" data-act="sendHelp">Send</button></div>
      <button type="button" class="btn bad" data-act="toast" data-msg="Safety report opened. A person reviews it within 24 hours.">${I('flag')} Report a safety concern</button>`, { back: 'P18' }); } };
ACT.faq = (el, d) => { U.f.faq = U.f.faq === +d.i ? null : +d.i; render(); };
ACT.sendHelp = () => { if (!(U.f.msg || '').trim()) return toast('Write a message first.'); U.f.msg = ''; render(); toast('Sent. We reply within one working day.'); };
